export const activeCourses: ReadonlySet<string> = new Set(
  RAW.split('\n').flatMap((line) => {
    const [subject, ...numbers] = line.split(' ')
    return numbers.map((number) => subject + number)
  }),
)

/** Whether the 2026-27 catalogue lists this code at all (offered this year or not). */
export const isActiveCourse = (code: string): boolean => activeCourses.has(code)
